def factorial_recursive(n):
    """Kinakalkula ang factorial ng n gamit ang recursion."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("Ang input ay dapat isang non-negative integer.")

    # Batayang kaso
    if n == 0:
        return 1

    # Hakbang ng recursion
    return n * factorial_recursive(n - 1)

# Halimbawa ng paggamit:
# print(factorial_recursive(5))  # Nagbabalik ng 120
# print(factorial_recursive(0))  # Nagbabalik ng 1

