def factorial_recursive(n):
    """
    Kinakalkula ang factorial ng isang non-negative integer n gamit ang recursion.
    Ang Factorial ng 0 ay tinukoy bilang 1.

    Raises:
        ValueError: Kung si n ay negatibo.
    """
    if n < 0:
        raise ValueError("Ang Factorial ay hindi tinukoy para sa mga negatibong numero.")
    elif n == 0:
        return 1
    else:
        return n * factorial_recursive(n - 1)

# Halimbawa ng paggamit:
# print(factorial_recursive(5)) # Output: 120

