def fibonacci_recursive(n):
    """Kinakalkula ang ika-nth Fibonacci number gamit ang recursion.
    Nagbabalik ng 0 para sa mga input na hindi positive.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

